"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base class for all microdb errors."""


class LexError(MicroDBError):
    """Raised when the lexer encounters an invalid character."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class ParseError(MicroDBError):
    """Raised when the parser encounters invalid syntax."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class SchemaError(MicroDBError):
    """Raised when a Table's schema or data is invalid."""


class TypeMismatchError(MicroDBError):
    """Raised when an operation is applied to incompatible types."""


class UnknownColumnError(MicroDBError):
    """Raised when a referenced column does not exist."""


class AmbiguousColumnError(MicroDBError):
    """Raised when an unqualified column name matches more than one table."""


class UnknownTableError(MicroDBError):
    """Raised when a table qualifier does not refer to a known table."""


class UnknownFunctionError(MicroDBError):
    """Raised when a function name is not recognized."""


class ArityError(MicroDBError):
    """Raised when a function call has the wrong number of arguments."""


class AggregateError(MicroDBError):
    """Raised when an aggregate is used in a disallowed position."""


class GroupingError(MicroDBError):
    """Raised when a SELECT item is not an aggregate or grouping expression."""

"""The value model: five value kinds and three-valued logic.

NULL is represented by Python's ``None`` and is not a distinct "type" -- it is
the absence of a value permitted in any column.  ``bool`` is always treated as
a distinct kind from ``int``, even though ``isinstance(True, int)`` is true in
Python, so every numeric check here explicitly excludes ``bool``.
"""

from __future__ import annotations

from microdb.errors import TypeMismatchError

Value = object  # int | float | str | bool | None


def type_of(v: Value) -> str:
    """Return the microdb type name of ``v``: INT, FLOAT, TEXT, BOOL or NULL."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported value: {v!r}")


def is_numeric(v: Value) -> bool:
    """Return True if v is an INT or FLOAT (not BOOL, not NULL)."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND."""
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR."""
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT."""
    if a is None:
        return None
    return not a


def compare_eq(a: Value, b: Value) -> bool | None:
    """Three-valued equality comparison."""
    if a is None or b is None:
        return None
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return a == b
        raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")
    if is_numeric(a) and is_numeric(b):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")


def compare_lt(a: Value, b: Value) -> bool | None:
    """Three-valued less-than comparison."""
    if a is None or b is None:
        return None
    if isinstance(a, bool) or isinstance(b, bool):
        if isinstance(a, bool) and isinstance(b, bool):
            return bool(a) < bool(b)
        raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")
    if is_numeric(a) and is_numeric(b):
        return a < b
    if isinstance(a, str) and isinstance(b, str):
        return a < b
    raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")


def _check_numeric(a: Value, b: Value) -> None:
    if not is_numeric(a) or not is_numeric(b):
        raise TypeMismatchError(f"arithmetic requires numeric operands, got {type_of(a)} and {type_of(b)}")


def arith(op: str, a: Value, b: Value) -> Value:
    """Apply arithmetic operator op in '+-*/%' to a and b, per section 3.2."""
    if a is None or b is None:
        return None
    if op == "%":
        if not isinstance(a, int) or not isinstance(b, int) or isinstance(a, bool) or isinstance(b, bool):
            raise TypeMismatchError("% requires two INT operands")
        if b == 0:
            return None
        return a % b
    _check_numeric(a, b)
    if op == "/":
        if b == 0:
            return None
        return float(a) / float(b)
    if op in ("+", "-", "*"):
        result = {"+": a + b, "-": a - b, "*": a * b}[op]
        if isinstance(a, float) or isinstance(b, float):
            return float(result)
        return int(result)
    raise TypeMismatchError(f"unknown operator: {op}")


def negate(a: Value) -> Value:
    """Unary negation; preserves type; NULL propagates."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"cannot negate {type_of(a)}")
    return -a

"""Schema layer: Column and Table."""

from __future__ import annotations

import dataclasses

from microdb.errors import SchemaError

VALID_TYPES = {"INT", "FLOAT", "TEXT", "BOOL"}


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


def _check_cell(value: object, col: Column, row_index: int) -> object:
    """Validate/coerce a single cell against its column type; returns the stored value."""
    if value is None:
        return None
    if col.type == "BOOL":
        if not isinstance(value, bool):
            raise SchemaError(f"row {row_index}: column {col.name!r} expects BOOL")
        return value
    if col.type == "INT":
        if isinstance(value, bool) or not isinstance(value, int):
            raise SchemaError(f"row {row_index}: column {col.name!r} expects INT")
        return value
    if col.type == "FLOAT":
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise SchemaError(f"row {row_index}: column {col.name!r} expects FLOAT")
        return float(value)
    if col.type == "TEXT":
        if not isinstance(value, str):
            raise SchemaError(f"row {row_index}: column {col.name!r} expects TEXT")
        return value
    raise SchemaError(f"unreachable: unknown type {col.type!r}")


class Table:
    """An in-memory table: a fixed list of typed columns plus rows of values."""

    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        if not columns:
            raise SchemaError("a table must have at least one column")
        seen: set[str] = set()
        for col in columns:
            if col.type not in VALID_TYPES:
                raise SchemaError(f"unknown column type: {col.type!r}")
            if col.name in seen:
                raise SchemaError(f"duplicate column name: {col.name!r}")
            seen.add(col.name)
        checked_rows: list[list[object]] = []
        for row_index, row in enumerate(rows):
            if len(row) != len(columns):
                raise SchemaError(f"row {row_index} has {len(row)} cells, expected {len(columns)}")
            checked_rows.append([_check_cell(v, c, row_index) for v, c in zip(row, columns)])
        self._name = name
        self._columns = list(columns)
        self._rows = checked_rows

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for i, col in enumerate(self._columns):
            if col.name == name:
                return i
        raise SchemaError(f"unknown column: {name!r}")

"""Lexer: tokenize a microdb query string."""

from __future__ import annotations

import dataclasses

from microdb.errors import LexError

KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "INNER", "LEFT", "JOIN", "ON", "WHERE",
    "GROUP", "BY", "HAVING", "ORDER", "ASC", "DESC", "LIMIT", "OFFSET",
    "AS", "AND", "OR", "NOT", "IS", "NULL", "TRUE", "FALSE",
}

_MULTI_OPS = ("<>", "<=", ">=")
_SINGLE_OPS = "=<>+-*/%(),."


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str  # "KEYWORD" | "IDENT" | "INT" | "FLOAT" | "TEXT" | "OP" | "EOF"
    value: object
    start: int
    end: int


def _is_ident_start(ch: str) -> bool:
    return ch.isalpha() or ch == "_"


def _is_ident_part(ch: str) -> bool:
    return ch.isalnum() or ch == "_"


def _read_text_literal(src: str, i: int) -> tuple[str, int]:
    start = i
    i += 1
    parts: list[str] = []
    while True:
        if i >= len(src):
            raise LexError("unterminated text literal", start)
        ch = src[i]
        if ch == "'":
            if i + 1 < len(src) and src[i + 1] == "'":
                parts.append("'")
                i += 2
                continue
            i += 1
            break
        parts.append(ch)
        i += 1
    return "".join(parts), i


def _read_number(src: str, i: int) -> tuple[Token, int]:
    start = i
    is_float = False
    while i < len(src) and src[i].isdigit():
        i += 1
    if i < len(src) and src[i] == ".":
        is_float = True
        i += 1
        while i < len(src) and src[i].isdigit():
            i += 1
    if i < len(src) and src[i] in "eE":
        save = i
        j = i + 1
        if j < len(src) and src[j] in "+-":
            j += 1
        if j < len(src) and src[j].isdigit():
            is_float = True
            j += 1
            while j < len(src) and src[j].isdigit():
                j += 1
            i = j
        else:
            i = save
    text = src[start:i]
    if is_float:
        return Token("FLOAT", float(text), start, i), i
    return Token("INT", int(text), start, i), i


def tokenize(src: str) -> list[Token]:
    """Tokenize src into a list of Tokens, terminated by an EOF token."""
    tokens: list[Token] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if ch == "-" and i + 1 < n and src[i + 1] == "-":
            while i < n and src[i] != "\n":
                i += 1
            continue
        if ch == "'":
            text, new_i = _read_text_literal(src, i)
            tokens.append(Token("TEXT", text, i, new_i))
            i = new_i
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and src[i + 1].isdigit()):
            tok, new_i = _read_number(src, i)
            tokens.append(tok)
            i = new_i
            continue
        if _is_ident_start(ch):
            start = i
            i += 1
            while i < n and _is_ident_part(src[i]):
                i += 1
            text = src[start:i]
            upper = text.upper()
            if upper in KEYWORDS:
                tokens.append(Token("KEYWORD", upper, start, i))
            else:
                tokens.append(Token("IDENT", text, start, i))
            continue
        matched = False
        for op in _MULTI_OPS:
            if src.startswith(op, i):
                tokens.append(Token("OP", op, i, i + len(op)))
                i += len(op)
                matched = True
                break
        if matched:
            continue
        if ch in _SINGLE_OPS:
            tokens.append(Token("OP", ch, i, i + 1))
            i += 1
            continue
        raise LexError(f"unexpected character {ch!r}", i)
    tokens.append(Token("EOF", None, n, n))
    return tokens

"""Parser: token stream -> Query AST."""

from __future__ import annotations

import dataclasses
import re
from typing import Optional, Union

from microdb.errors import ParseError
from microdb.lexer import Token, tokenize

AGGREGATE_NAMES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
_WS_RE = re.compile(r"\s+")


def collapse_whitespace(text: str) -> str:
    return _WS_RE.sub(" ", text.strip())


@dataclasses.dataclass(frozen=True)
class Literal:
    value: object
    start: int
    end: int


@dataclasses.dataclass(frozen=True)
class ColumnRef:
    table: Optional[str]
    name: str
    start: int
    end: int


@dataclasses.dataclass(frozen=True)
class Star:
    table: Optional[str]
    start: int
    end: int


@dataclasses.dataclass(frozen=True)
class FuncCall:
    name: str
    args: list
    star: bool
    start: int
    end: int


@dataclasses.dataclass(frozen=True)
class UnaryOp:
    op: str
    operand: object
    start: int
    end: int


@dataclasses.dataclass(frozen=True)
class BinOp:
    op: str
    left: object
    right: object
    start: int
    end: int


@dataclasses.dataclass(frozen=True)
class IsNull:
    expr: object
    negated: bool
    start: int
    end: int


Expr = Union[Literal, ColumnRef, FuncCall, UnaryOp, BinOp, IsNull]


@dataclasses.dataclass(frozen=True)
class SelectItem:
    expr: object  # Expr | Star
    alias: Optional[str]
    default_name: str


@dataclasses.dataclass(frozen=True)
class JoinClause:
    kind: str
    table: str
    on: Expr


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: Expr
    desc: bool


@dataclasses.dataclass(frozen=True)
class Query:
    distinct: bool
    select_items: list
    from_table: str
    join: Optional[JoinClause]
    where: Optional[Expr]
    group_by: list
    having: Optional[Expr]
    order_by: list
    limit: Optional[int]
    offset: Optional[int]


def _contains_aggregate_call(expr: object) -> bool:
    if isinstance(expr, FuncCall):
        if expr.name.upper() in AGGREGATE_NAMES:
            return True
        return any(_contains_aggregate_call(a) for a in expr.args)
    if isinstance(expr, (UnaryOp,)):
        return _contains_aggregate_call(expr.operand)
    if isinstance(expr, BinOp):
        return _contains_aggregate_call(expr.left) or _contains_aggregate_call(expr.right)
    if isinstance(expr, IsNull):
        return _contains_aggregate_call(expr.expr)
    return False


class Parser:
    def __init__(self, tokens: list[Token], src: str) -> None:
        self.tokens = tokens
        self.pos = 0
        self.src = src

    def _peek(self) -> Token:
        return self.tokens[self.pos]

    def _advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _expect_kw(self, kw: str) -> Token:
        tok = self._peek()
        if tok.kind == "KEYWORD" and tok.value == kw:
            return self._advance()
        raise ParseError(f"expected {kw!r}, got {tok.kind} {tok.value!r}", tok.start)

    def _expect_op(self, op: str) -> Token:
        tok = self._peek()
        if tok.kind == "OP" and tok.value == op:
            return self._advance()
        raise ParseError(f"expected {op!r}, got {tok.kind} {tok.value!r}", tok.start)

    def _is_kw(self, kw: str) -> bool:
        tok = self._peek()
        return tok.kind == "KEYWORD" and tok.value == kw

    def _is_op(self, op: str) -> bool:
        tok = self._peek()
        return tok.kind == "OP" and tok.value == op

    def _expect_ident(self) -> Token:
        tok = self._peek()
        if tok.kind == "IDENT":
            return self._advance()
        raise ParseError(f"expected identifier, got {tok.kind} {tok.value!r}", tok.start)

    # ---- expression grammar ----

    def parse_or_expr(self) -> object:
        start = self._peek().start
        left = self.parse_and_expr()
        while self._is_kw("OR"):
            self._advance()
            right = self.parse_and_expr()
            left = BinOp("OR", left, right, start, self.tokens[self.pos - 1].end)
        return left

    def parse_and_expr(self) -> object:
        start = self._peek().start
        left = self.parse_not_expr()
        while self._is_kw("AND"):
            self._advance()
            right = self.parse_not_expr()
            left = BinOp("AND", left, right, start, self.tokens[self.pos - 1].end)
        return left

    def parse_not_expr(self) -> object:
        if self._is_kw("NOT"):
            start = self._advance().start
            operand = self.parse_not_expr()
            return UnaryOp("NOT", operand, start, self.tokens[self.pos - 1].end)
        return self.parse_predicate()

    _CMP_OPS = {"=", "<>", "<", "<=", ">", ">="}

    def parse_predicate(self) -> object:
        start = self._peek().start
        left = self.parse_additive()
        tok = self._peek()
        if tok.kind == "OP" and tok.value in self._CMP_OPS:
            op = self._advance().value
            right = self.parse_additive()
            return BinOp(op, left, right, start, self.tokens[self.pos - 1].end)
        if tok.kind == "KEYWORD" and tok.value == "IS":
            self._advance()
            negated = False
            if self._is_kw("NOT"):
                self._advance()
                negated = True
            self._expect_kw("NULL")
            return IsNull(left, negated, start, self.tokens[self.pos - 1].end)
        return left

    def parse_additive(self) -> object:
        start = self._peek().start
        left = self.parse_multiplicative()
        while self._peek().kind == "OP" and self._peek().value in ("+", "-"):
            op = self._advance().value
            right = self.parse_multiplicative()
            left = BinOp(op, left, right, start, self.tokens[self.pos - 1].end)
        return left

    def parse_multiplicative(self) -> object:
        start = self._peek().start
        left = self.parse_unary()
        while self._peek().kind == "OP" and self._peek().value in ("*", "/", "%"):
            op = self._advance().value
            right = self.parse_unary()
            left = BinOp(op, left, right, start, self.tokens[self.pos - 1].end)
        return left

    def parse_unary(self) -> object:
        if self._is_op("-"):
            start = self._advance().start
            operand = self.parse_unary()
            return UnaryOp("-", operand, start, self.tokens[self.pos - 1].end)
        return self.parse_primary()

    def parse_primary(self) -> object:
        tok = self._peek()
        if tok.kind in ("INT", "FLOAT", "TEXT"):
            self._advance()
            return Literal(tok.value, tok.start, tok.end)
        if tok.kind == "KEYWORD" and tok.value == "TRUE":
            self._advance()
            return Literal(True, tok.start, tok.end)
        if tok.kind == "KEYWORD" and tok.value == "FALSE":
            self._advance()
            return Literal(False, tok.start, tok.end)
        if tok.kind == "KEYWORD" and tok.value == "NULL":
            self._advance()
            return Literal(None, tok.start, tok.end)
        if tok.kind == "IDENT":
            return self._parse_ident_primary()
        if tok.kind == "OP" and tok.value == "(":
            self._advance()
            inner = self.parse_or_expr()
            end_tok = self._expect_op(")")
            return dataclasses.replace(inner, start=tok.start, end=end_tok.end) if False else _reparen(inner, tok.start, end_tok.end)
        raise ParseError(f"unexpected token {tok.kind} {tok.value!r}", tok.start)

    def _parse_ident_primary(self) -> object:
        tok = self._advance()
        if self._is_op("("):
            return self._parse_func_call(tok)
        if self._is_op(".") and self.tokens[self.pos + 1].kind == "IDENT":
            self._advance()
            name_tok = self._advance()
            return ColumnRef(tok.value, name_tok.value, tok.start, name_tok.end)
        return ColumnRef(None, tok.value, tok.start, tok.end)

    def _parse_func_call(self, name_tok: Token) -> object:
        self._advance()  # (
        name_upper = name_tok.value.upper()
        if name_upper == "COUNT" and self._is_op("*"):
            self._advance()
            end_tok = self._expect_op(")")
            return FuncCall(name_tok.value, [], True, name_tok.start, end_tok.end)
        args = []
        if not self._is_op(")"):
            args.append(self.parse_or_expr())
            while self._is_op(","):
                self._advance()
                args.append(self.parse_or_expr())
        end_tok = self._expect_op(")")
        call = FuncCall(name_tok.value, args, False, name_tok.start, end_tok.end)
        if name_upper in AGGREGATE_NAMES:
            for a in args:
                if _contains_aggregate_call(a):
                    raise ParseError("aggregate functions may not nest", name_tok.start)
        return call

    # ---- clauses ----

    def parse_select_item(self) -> SelectItem:
        start = self._peek().start
        if self._is_op("*"):
            tok = self._advance()
            return SelectItem(Star(None, tok.start, tok.end), None, "*")
        if (self._peek().kind == "IDENT" and self.tokens[self.pos + 1].kind == "OP"
                and self.tokens[self.pos + 1].value == "." and self.tokens[self.pos + 2].kind == "OP"
                and self.tokens[self.pos + 2].value == "*"):
            table_tok = self._advance()
            self._advance()
            star_tok = self._advance()
            name = f"{table_tok.value}.*"
            return SelectItem(Star(table_tok.value, table_tok.start, star_tok.end), None, name)
        expr = self.parse_or_expr()
        end = self.tokens[self.pos - 1].end
        alias = None
        if self._is_kw("AS"):
            self._advance()
            alias = self._expect_ident().value
        if alias is not None:
            default_name = alias
        elif isinstance(expr, ColumnRef):
            default_name = expr.name
        else:
            default_name = collapse_whitespace(self.src[start:end])
        return SelectItem(expr, alias, default_name)

    def parse_query(self) -> Query:
        self._expect_kw("SELECT")
        distinct = False
        if self._is_kw("DISTINCT"):
            self._advance()
            distinct = True
        select_items = [self.parse_select_item()]
        while self._is_op(","):
            self._advance()
            select_items.append(self.parse_select_item())
        self._expect_kw("FROM")
        from_table = self._expect_ident().value
        join = self._parse_join()
        where = None
        if self._is_kw("WHERE"):
            self._advance()
            where = self.parse_or_expr()
        group_by = self._parse_group_by()
        having = None
        if self._is_kw("HAVING"):
            self._advance()
            having = self.parse_or_expr()
        order_by = self._parse_order_by()
        limit = self._parse_int_clause("LIMIT")
        offset = self._parse_int_clause("OFFSET")
        tok = self._peek()
        if tok.kind != "EOF":
            raise ParseError(f"unexpected token {tok.kind} {tok.value!r}", tok.start)
        return Query(distinct, select_items, from_table, join, where, group_by, having, order_by, limit, offset)

    def _parse_join(self) -> Optional[JoinClause]:
        kind = None
        if self._is_kw("INNER"):
            self._advance()
            kind = "INNER"
        elif self._is_kw("LEFT"):
            self._advance()
            kind = "LEFT"
        if self._is_kw("JOIN"):
            self._advance()
            kind = kind or "INNER"
            table = self._expect_ident().value
            self._expect_kw("ON")
            on_expr = self.parse_or_expr()
            return JoinClause(kind, table, on_expr)
        if kind is not None:
            raise ParseError("expected JOIN", self._peek().start)
        return None

    def _parse_group_by(self) -> list:
        group_by = []
        if self._is_kw("GROUP"):
            self._advance()
            self._expect_kw("BY")
            group_by.append(self.parse_or_expr())
            while self._is_op(","):
                self._advance()
                group_by.append(self.parse_or_expr())
        return group_by

    def _parse_order_by(self) -> list:
        order_by = []
        if self._is_kw("ORDER"):
            self._advance()
            self._expect_kw("BY")
            order_by.append(self._parse_order_item())
            while self._is_op(","):
                self._advance()
                order_by.append(self._parse_order_item())
        return order_by

    def _parse_order_item(self) -> OrderItem:
        expr = self.parse_or_expr()
        desc = False
        if self._is_kw("ASC"):
            self._advance()
        elif self._is_kw("DESC"):
            self._advance()
            desc = True
        return OrderItem(expr, desc)

    def _parse_int_clause(self, kw: str) -> Optional[int]:
        if self._is_kw(kw):
            self._advance()
            tok = self._peek()
            if tok.kind != "INT":
                raise ParseError(f"expected integer after {kw}", tok.start)
            self._advance()
            return tok.value
        return None


def _reparen(inner: object, start: int, end: int) -> object:
    return dataclasses.replace(inner, start=start, end=end)


def parse(query: str) -> Query:
    """Parse a query string into a Query AST."""
    tokens = tokenize(query)
    parser = Parser(tokens, query)
    return parser.parse_query()

